#!/usr/bin/env node
/**
 * The 3D previews beside every plan: plans/<slug>/plan-3d.poster.{webp,png}, plan.glb and, for
 * Villa La Rotonda, plan-3d.replay.mp4, plus assets/3d-manifest.json (source SHA-256, frame hash,
 * GLB hashes, bytes). Generated by archlang's `gen:3d-assets` (packages/archlang-3d), never by hand.
 *
 *   node scripts/preview3d.mjs            regenerate everything (heavy: Chromium + ffmpeg)
 *   node scripts/preview3d.mjs --check    sources and files still match the manifest (no browser)
 *
 * Needs an archlang checkout (built, `npm ci` done) at $ARCHLANG_DIR, default ../archlang. The
 * generator runs from this directory so the manifest records repo-relative `plans/<slug>/plan.arch`.
 * Only Villa La Rotonda gets an MP4 (the budget is 1.5 MB each); the rest are poster and GLB.
 */
import { spawnSync } from "node:child_process";
import { copyFileSync, existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const AL = resolve(process.env.ARCHLANG_DIR ?? join(ROOT, "..", "archlang"));
const MANIFEST = join(ROOT, "assets", "3d-manifest.json");
const WITH_VIDEO = ["villa-rotonda"];
const PLANS = [
  "villa-rotonda", "west-wing", "railroad-apartment", "tweet-house",
  "dust2", "skeld", "bag-end", "friends-apartments", "evergreen-terrace", "dunder-mifflin", "mccallister-house",
];
// generator output name -> file in plans/<slug>/
const RENAME = { "poster.webp": "plan-3d.poster.webp", "poster.png": "plan-3d.poster.png", "glb": "plan.glb", "replay.mp4": "plan-3d.replay.mp4" };

const sha = (p) => createHash("sha256").update(readFileSync(p)).digest("hex");

if (process.argv.includes("--check")) {
  const m = JSON.parse(readFileSync(MANIFEST, "utf8"));
  const bad = [];
  for (const a of m.assets) {
    if (sha(join(ROOT, a.source.path)) !== a.source.sha256) bad.push(`${a.name}: plan.arch changed since its 3D preview was generated`);
    for (const f of a.files) {
      const p = join(ROOT, f.path);
      if (!existsSync(p)) bad.push(`${f.path}: missing`);
      else if (statSync(p).size !== f.bytes) bad.push(`${f.path}: bytes differ from the manifest`);
    }
  }
  for (const s of PLANS) if (!m.assets.some((a) => a.name === s)) bad.push(`${s}: not in the manifest`);
  if (bad.length) { console.error(bad.join("\n")); process.exit(1); }
  console.log(`preview3d: ${m.assets.length} plans match the manifest`);
  process.exit(0);
}

const tsx = join(AL, "node_modules", ".bin", process.platform === "win32" ? "tsx.cmd" : "tsx");
const pkg = join(AL, "packages", "archlang-3d");
const gen = (out, slugs, extra) => {
  const args = [join(pkg, "scripts", "gen-3d-assets.ts"), "--out", out, ...extra, ...slugs.flatMap((s) => ["--plan", `${s}=plans/${s}/plan.arch`])];
  const r = spawnSync(tsx, ["--tsconfig", join(pkg, "tsconfig.json"), ...args], { cwd: ROOT, stdio: "inherit", shell: process.platform === "win32" });
  if (r.status !== 0) throw new Error("gen:3d-assets failed");
};

const tmp = mkdtempSync(join(tmpdir(), "showcase-3d-"));
try {
  const a = join(tmp, "a"), b = join(tmp, "b");
  gen(a, PLANS.filter((s) => !WITH_VIDEO.includes(s)), ["--no-video"]);
  gen(b, WITH_VIDEO, []);
  const assets = [];
  for (const dir of [b, a]) {
    const m = JSON.parse(readFileSync(join(dir, "manifest.json"), "utf8"));
    for (const e of m.assets) {
      const files = [];
      for (const [from, to] of Object.entries(RENAME)) {
        const src = join(dir, `${e.name}.${from}`);
        if (!existsSync(src)) continue;
        const dest = join(ROOT, "plans", e.name, to);
        copyFileSync(src, dest);
        const was = e.files.find((f) => f.path === `${e.name}.${from}`);
        files.push({ path: `plans/${e.name}/${to}`, bytes: statSync(dest).size, archlang: was?.archlang, archlang3d: was?.archlang3d });
      }
      // The plan PNG is not shipped: the showcase has its own 2D covers.
      const { plan: _plan, files: _files, ...rest } = e;
      assets.push({ ...rest, files });
    }
  }
  assets.sort((x, y) => PLANS.indexOf(x.name) - PLANS.indexOf(y.name));
  mkdirSync(dirname(MANIFEST), { recursive: true });
  writeFileSync(
    MANIFEST,
    JSON.stringify({ about: "Generated by `npm run preview3d` (scripts/preview3d.mjs, via archlang's gen:3d-assets); never hand-edit. Freshness: `npm run preview3d:check`.", assets }, null, 2) + "\n",
  );
  console.log(`preview3d: ${assets.length} plans, manifest written`);
} finally {
  rmSync(tmp, { recursive: true, force: true });
}
